  { const h = $h("h_honest"); if (h) h.textContent = `Demo market · paper money · seed ${CLK.seed} · Past demo results do not predict real results. · Paper Trader ${typeof APP_BUILD !== "undefined" ? APP_BUILD : ""}` }
