  for (const [d, r] of Object.entries(R)) { const lt = r.lastTrade, key = lt ? lt.sym + "|" + lt.t : ""; if (homeSeen["lt" + d] != null && key && key !== homeSeen["lt" + d] && lt.pnl >= 50 && !document.documentElement.classList.contains("nomotion")) { const ch = $h("hmd" + d), fl = $h("hm_float"); if (ch) { ch.classList.remove("fl-big"); void ch.offsetWidth; ch.classList.add("fl-big") } if (fl) { fl.textContent = sg(lt.pnl); fl.classList.remove("go"); void fl.offsetWidth; fl.classList.add("go") } } homeSeen["lt" + d] = key }
