// Hall of fame (A1): best / worst trade, best day, current win streak — all from this run's real data
function fame() { let best = null, worst = null; for (const [d, r] of Object.entries(R)) for (const c of [r.best, r.worst]) { if (!c) continue; const x = Object.assign({ desk: DN[d - 1] }, c); if (!best || x.pnl > best.pnl) best = x; if (!worst || x.pnl < worst.pnl) worst = x }
  const m = SNAP ? metrics() : null, all = []; for (const r of Object.values(R)) for (const c of r.tail || []) all.push(c); all.sort((a, b) => b.t - a.t); let streak = 0; for (const c of all) { if (c.pnl > 0) streak++; else break }
  return { best, worst, bestDay: m && m.best, worstDay: m && m.worst, streak, capped: streak === all.length && all.length > 0 } }
function drawFame() { const el = $h("h_fame"); if (!el || !SNAP) return; const F = fame(); el.innerHTML = F.best ? `<div class="kv"><div><span>Best trade</span><b class="g">${sg(F.best.pnl)}</b><span>${escH(F.best.sym)} · ${escH(F.best.desk)} · ${escH(reasonN(F.best.reason))}</span></div><div><span>Worst trade</span><b class="r">${sg(F.worst.pnl)}</b><span>${escH(F.worst.sym)} · ${escH(F.worst.desk)} · ${escH(reasonN(F.worst.reason))}</span></div><div><span>Best day</span><b class="g">${F.bestDay ? SG$(F.bestDay.net) : "–"}</b><span>${F.bestDay ? "Day " + F.bestDay.day : ""}</span></div><div><span>Current win streak</span><b>${F.streak}${F.capped ? "+" : ""}</b><span>trades in a row that made money</span></div></div>` : '<div class="sub">Fills in after the first finished trades.</div>' }
setInterval(() => { if (cur === 0) drawFame() }, 1000);
