// Share card (A3): a clean result image (PNG) or copyable text
function shareText() { const D = reportData(); return `Paper Trader · demo market (paper money)\nProfit ${SG$(D.profit)} (${D.pct >= 0 ? "+" : ""}${D.pct.toFixed(2)}%)\nWin rate ${wrS(D.t.wn, D.t.ln)} · ${D.n.toLocaleString()} trades\nExpectancy ${SG$(Math.round(D.m.exp))}/trade · max drawdown ${D.m.ddPct.toFixed(2)}%\nSeed ${CLK.seed} · position size ${+MONEY.sizeMul || 1}x\nDemo results do not predict real results.` }
function shareCard() { const D = reportData(), c = document.createElement("canvas"); c.width = 1080; c.height = 1080; const x = c.getContext("2d"), g = x.createLinearGradient(0, 0, 1080, 1080); g.addColorStop(0, "#151a33"); g.addColorStop(1, "#05060c"); x.fillStyle = g; x.fillRect(0, 0, 1080, 1080);
  const T = (s, y, size, col, w) => { x.fillStyle = col; x.font = `${w || 600} ${size}px -apple-system,Segoe UI,Roboto,sans-serif`; x.fillText(s, 80, y) };
  T("PAPER TRADER · DEMO MARKET", 140, 34, "#8b93b8", 700); T("Profit", 260, 40, "#8b93b8"); T(SG$(D.profit), 380, 130, D.profit >= 0 ? "#2fd37a" : "#ff5a5f", 800); T(`${D.pct >= 0 ? "+" : ""}${D.pct.toFixed(2)}% · balance ${D$(D.final)}`, 450, 40, "#e8ebff");
  const rows = [["Win rate", wrS(D.t.wn, D.t.ln)], ["Trades", D.n.toLocaleString()], ["Expectancy", SG$(Math.round(D.m.exp)) + "/trade"], ["Max drawdown", D.m.ddPct.toFixed(2) + "%"]]; rows.forEach(([k, v], i) => { const yy = 580 + Math.floor(i / 2) * 170, xx = 80 + (i % 2) * 470; x.fillStyle = "#1c2240"; x.fillRect(xx, yy - 70, 440, 140); x.fillStyle = "#8b93b8"; x.font = "600 30px -apple-system,sans-serif"; x.fillText(k, xx + 30, yy - 20); x.fillStyle = "#fff"; x.font = "800 52px -apple-system,sans-serif"; x.fillText(v, xx + 30, yy + 45) });
  T(`Seed ${CLK.seed} · position size ${+MONEY.sizeMul || 1}x · paper money`, 960, 28, "#8b93b8"); T("Demo results do not predict real results.", 1005, 28, "#8b93b8");
  c.toBlob(b => { if (b) download("paper-trader-result.png", b, "image/png") }, "image/png") }
